using Microsoft.EntityFrameworkCore;
namespace Movers.DAL.Persistence;
public static class WarehouseReceiptSchema {
 public static Task Apply(MoversDbContext db) {
  var sql = db.Database.IsSqlServer() ? """
IF OBJECT_ID(N'dbo.WarehouseReceipts', N'U') IS NULL
BEGIN
 CREATE TABLE [WarehouseReceipts] ([SerialNo] int IDENTITY PRIMARY KEY, [Id] uniqueidentifier NOT NULL, [TenantId] uniqueidentifier NOT NULL, [RequestId] uniqueidentifier NOT NULL, [RequestHash] nvarchar(64) NOT NULL, [ReceiptNumber] nvarchar(40) NOT NULL, [Source] nvarchar(16) NOT NULL, [WarehouseId] uniqueidentifier NOT NULL, [PickupId] uniqueidentifier NULL, [ReceivedAtUtc] datetimeoffset NOT NULL, [ActorId] uniqueidentifier NOT NULL, [SnapshotJson] nvarchar(max) NOT NULL);
 CREATE UNIQUE INDEX [IX_WarehouseReceipts_Id] ON [WarehouseReceipts] ([Id]);
 CREATE UNIQUE INDEX [IX_WarehouseReceipts_TenantId_RequestId] ON [WarehouseReceipts] ([TenantId],[RequestId]);
 CREATE UNIQUE INDEX [IX_WarehouseReceipts_TenantId_ReceiptNumber] ON [WarehouseReceipts] ([TenantId],[ReceiptNumber]);
END
""" : db.Database.IsNpgsql() ? """
CREATE TABLE IF NOT EXISTS "WarehouseReceipts" ("SerialNo" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "Id" uuid NOT NULL UNIQUE, "TenantId" uuid NOT NULL, "RequestId" uuid NOT NULL, "RequestHash" varchar(64) NOT NULL, "ReceiptNumber" varchar(40) NOT NULL, "Source" varchar(16) NOT NULL, "WarehouseId" uuid NOT NULL, "PickupId" uuid NULL, "ReceivedAtUtc" timestamp with time zone NOT NULL, "ActorId" uuid NOT NULL, "SnapshotJson" text NOT NULL, UNIQUE ("TenantId", "RequestId"), UNIQUE ("TenantId", "ReceiptNumber"));
""" : """
CREATE TABLE IF NOT EXISTS "WarehouseReceipts" ("SerialNo" INTEGER PRIMARY KEY AUTOINCREMENT, "Id" TEXT NOT NULL UNIQUE, "TenantId" TEXT NOT NULL, "RequestId" TEXT NOT NULL, "RequestHash" TEXT NOT NULL, "ReceiptNumber" TEXT NOT NULL, "Source" TEXT NOT NULL, "WarehouseId" TEXT NOT NULL, "PickupId" TEXT NULL, "ReceivedAtUtc" TEXT NOT NULL, "ActorId" TEXT NOT NULL, "SnapshotJson" TEXT NOT NULL, UNIQUE ("TenantId", "RequestId"), UNIQUE ("TenantId", "ReceiptNumber"));
""";
  return db.Database.ExecuteSqlRawAsync(sql);
 }
}
